function AdminMembers(){const [query,setQuery]=useState(''),[plan,setPlan]=useState('All plans'),[status,setStatus]=useState('All status'),[members,setMembers]=useState(initialMembers),[selected,setSelected]=useState<Member|null>(null),[addOpen,setAddOpen]=useState(false),[added,setAdded]=useState(false);const [name,setName]=useState(''),[email,setEmail]=useState(''),[trainer,setTrainer]=useState('');const filtered=useMemo(()=>members.filter(m=>`${m.name} ${m.email} ${m.trainer}`.toLowerCase().includes(query.toLowerCase())&&(plan==='All plans'||m.plan===plan)&&(status==='All status'||m.status===status)),[members,plan,query,status]);const addMember=()=>{if(!name.trim()||!email.trim())return;const initials=name.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();setMembers(cur=>[{name:name.trim(),initials,email:email.trim(),plan:'Pro',trainer:trainer.trim()||'Unassigned',joined:'Today',attendance:'—',status:'New',tone:'bg-[#cbd8f0]'},...cur]);setAdded(true);};const statusClass=(s:string)=>s==='At risk'?'bg-[#fff0e7] text-[#c66735]':s==='New'?'bg-[#e1f0ed] text-[#0f6268]':'bg-[#eff7c9] text-[#537000]';return <Shell owner title="Members" eyebrow="RepFit Fitness Center · Admin"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Link href="/admin" className="mb-4 flex items-center gap-2 text-xs font-bold text-[#0f6268]"><ArrowLeft size={14}/> Back to overview</Link><p className="text-xs font-bold uppercase tracking-[.18em] text-[#0f6268]">Member directory</p><h2 className="repfi-display mt-2 text-3xl font-bold sm:text-4xl">Know every member.</h2><p className="mt-2 max-w-xl text-sm text-[#70808c]">Search your community, review attendance, and keep every member moving forward.</p></div><button onClick={()=>{setAdded(false);setName('');setEmail('');setTrainer('');setAddOpen(true)}} data-testid="button-add-member-directory" className="flex items-center justify-center gap-2 rounded-xl bg-[#20334a] px-5 py-3 text-sm font-bold text-white"><Plus size={16}/> Add member</button></div><div className="mt-8 grid gap-4 sm:grid-cols-3"><Metric label="Total members" value="1,248" detail="+8.4% this month"/><Metric label="Active this week" value="982" detail="78.7% of your community" accent="teal"/><Metric label="Needs attention" value="34" detail="Members below 50% attendance" accent="orange"/></div><section className="repfi-card mt-8 overflow-hidden"><div className="border-b border-[#dfe7e3] p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center"><Heading kicker="Live directory" title={`${filtered.length} members showing`}/><div className="flex flex-col gap-2 sm:flex-row"><div className="min-w-[240px]"><SearchBox value={query} onChange={setQuery} placeholder="Search members"/></div><label className="flex items-center gap-2 rounded-xl border border-[#dfe7e3] bg-[#fbfcfa] px-3 text-xs font-bold text-[#70808c]"><SlidersHorizontal size={15}/><select data-testid="select-member-plan" value={plan} onChange={e=>setPlan(e.target.value)} className="bg-transparent py-2.5 outline-none">{['All plans','Basic','Pro','Elite'].map(x=><option key={x}>{x}</option>)}</select></label><select data-testid="select-member-status" value={status} onChange={e=>setStatus(e.target.value)} className="rounded-xl border border-[#dfe7e3] bg-[#fbfcfa] px-3 py-2.5 text-xs font-bold text-[#70808c] outline-none">{['All status','Active','New','At risk'].map(x=><option key={x}>{x}</option>)}</select></div></div></div><div className="overflow-x-auto"><div className="min-w-[930px]"><div className="grid grid-cols-[1.6fr_1.25fr_.65fr_1.05fr_.65fr_.7fr_.45fr] gap-4 border-b border-[#dfe7e3] px-6 py-3 text-[10px] font-bold uppercase tracking-[.14em] text-[#9aa8aa]"><span>Member</span><span>Trainer</span><span>Plan</span><span>Joined</span><span>Attendance</span><span>Status</span><span/></div>{filtered.length?filtered.map((m,i)=><div key={m.email} data-testid={`row-member-${i}`} className="grid grid-cols-[1.6fr_1.25fr_.65fr_1.05fr_.65fr_.7fr_.45fr] items-center gap-4 border-b border-[#e9efea] px-6 py-4 text-sm transition hover:bg-[#f7faf5]"><button onClick={()=>setSelected(m)} data-testid={`button-profile-${m.initials}`} className="flex min-w-0 items-center gap-3 text-left"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-full text-[10px] font-bold text-[#20334a] ${m.tone}`}>{m.initials}</span><span className="min-w-0"><b className="block truncate">{m.name}</b><span className="mt-1 block truncate text-[11px] text-[#70808c]">{m.email}</span></span></button><span className="truncate text-xs text-[#70808c]">{m.trainer}</span><span className="text-xs font-bold">{m.plan}</span><span className="text-xs text-[#70808c]">{m.joined}</span><span className={`text-xs font-bold ${m.attendance!=='—'&&Number.parseInt(m.attendance)<50?'text-[#c66735]':'text-[#0f6268]'}`}>{m.attendance}</span><span className={`w-fit rounded-full px-2.5 py-1 text-[10px] font-bold ${statusClass(m.status)}`}>{m.status}</span><button onClick={()=>setSelected(m)} data-testid={`button-member-actions-${m.initials}`} aria-label={`More about ${m.name}`} className="justify-self-end rounded-lg p-2 text-[#70808c]"><MoreHorizontal size={17}/></button></div>):<div className="grid place-items-center px-6 py-16 text-center"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-[#eff7c9] text-[#537000]"><Search size={19}/></span><p className="mt-4 font-bold">No members match those filters.</p><button onClick={()=>{setQuery('');setPlan('All plans');setStatus('All status')}} className="mt-2 text-xs font-bold text-[#0f6268]">Clear filters</button></div>}</div></div></section><div className="mt-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-[#dfe7e3] bg-[#e1f0ed] px-5 py-4 text-xs"><span className="flex items-center gap-2 font-bold text-[#0f6268]"><Users size={16}/> Member data is updated in this demo workspace.</span><span data-testid="text-member-count" className="text-[#70808c]">Showing {filtered.length} of {members.length} demo profiles</span></div>{selected&&<Modal title="Member profile" onClose={()=>setSelected(null)}><div className="mt-5 flex items-center gap-3 rounded-2xl bg-[#e1f0ed] p-4"><Avatar initials={selected.initials} tone={selected.tone}/><div><p className="font-bold">{selected.name}</p><p className="mt-1 text-xs text-[#70808c]">{selected.email}</p></div></div><div className="mt-5 grid grid-cols-2 gap-3 text-xs">{[['Plan',selected.plan],['Attendance',selected.attendance],['Trainer',selected.trainer],['Status',selected.status]].map(([label,value])=><div key={label} className="rounded-xl bg-[#f5f7f4] p-3"><span className="text-[#70808c]">{label}</span><b className="mt-1 block">{value}</b></div>)}</div><button onClick={()=>setSelected(null)} className="mt-5 w-full rounded-xl bg-[#20334a] py-3 text-sm font-bold text-white">Close profile</button></Modal>}{addOpen&&<Modal title={added?'Member added':'Add a new member'} onClose={()=>setAddOpen(false)}>{added?<><div className="mt-5 rounded-2xl bg-[#eff7c9] p-4"><div className="flex items-center gap-2 font-bold"><Check size={16}/> {name} is ready for onboarding.</div><p className="mt-2 text-xs text-[#70808c]">The new demo profile now appears at the top of the directory.</p></div><button onClick={()=>setAddOpen(false)} className="mt-5 w-full rounded-xl bg-[#20334a] py-3 text-sm font-bold text-white">Done</button></>:<><div className="mt-5 space-y-3"><input required data-testid="input-new-member-name" value={name} onChange={e=>setName(e.target.value)} placeholder="Full name" className="w-full rounded-xl border border-[#dfe7e3] bg-[#f5f7f4] px-4 py-3 text-sm outline-none"/><input required type="email" data-testid="input-new-member-email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Email address" className="w-full rounded-xl border border-[#dfe7e3] bg-[#f5f7f4] px-4 py-3 text-sm outline-none"/><input data-testid="input-new-member-trainer" value={trainer} onChange={e=>setTrainer(e.target.value)} placeholder="Assign trainer (optional)" className="w-full rounded-xl border border-[#dfe7e3] bg-[#f5f7f4] px-4 py-3 text-sm outline-none"/></div><button onClick={addMember} data-testid="button-create-member" className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[#0f6268] py-3 text-sm font-bold text-white"><Plus size={16}/> Create member</button></>}</Modal>}</Shell>}
function Analytics(){const [period,setPeriod]=useState('Last 5 months');const trend=[{m:'Jan',members:920,attendance:61},{m:'Feb',members:978,attendance:65},{m:'Mar',members:1088,attendance:69},{m:'Apr',members:1170,attendance:72},{m:'May',members:1248,attendance:75}];const trainersData=[['Rahul Sharma','1,842','94%','bg-[#d7f35c]'],['Meera Iyer','1,420','91%','bg-[#f39a64]'],['Arjun Kapoor','1,196','88%','bg-[#a9d6ce]']];return <Shell owner title="Performance, at a glance" eyebrow="Business analytics"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-[#0f6268]">Owner intelligence</p><h2 className="repfi-display mt-2 text-3xl font-bold sm:text-4xl">Find the signal.</h2><p className="mt-2 text-sm text-[#70808c]">The numbers behind RepFit Fitness Center’s strongest month yet.</p></div><button onClick={()=>setPeriod(period==='Last 5 months'?'This year':'Last 5 months')} data-testid="button-analytics-period" className="flex items-center gap-2 self-start rounded-xl border border-[#dfe7e3] bg-[#fbfcfa] px-3 py-2.5 text-xs font-bold sm:self-auto">{period}<ChevronDown size={14}/></button></div><div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Member LTV" value="₹18,420" detail="+8.7% from last quarter"/><Metric label="Churn rate" value="3.8%" detail="-1.2 points this month" accent="teal"/><Metric label="Class utilization" value="82.4%" detail="+6.3 points" accent="orange"/><Metric label="Net revenue" value="₹8.42L" detail="+12.8% vs March"/></div><div className="mt-8 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><section className="repfi-card p-6"><Heading kicker="Growth overview" title="Members & attendance"/><div className="h-64"><ResponsiveContainer width="100%" height="100%"><LineChart data={trend}><CartesianGrid vertical={false} stroke="#e9efea"/><XAxis dataKey="m" axisLine={false} tickLine={false} tick={{fontSize:11,fill:muted}}/><YAxis yAxisId="left" axisLine={false} tickLine={false} tick={{fontSize:11,fill:muted}}/><YAxis yAxisId="right" orientation="right" axisLine={false} tickLine={false} tick={{fontSize:11,fill:muted}}/><ChartTooltip/><Line yAxisId="left" type="monotone" dataKey="members" stroke="#0f6268" strokeWidth={3} dot={{r:4,fill:'#0f6268'}}/><Line yAxisId="right" type="monotone" dataKey="attendance" stroke="#f39a64" strokeWidth={3} dot={{r:4,fill:'#f39a64'}}/></LineChart></ResponsiveContainer></div><div className="mt-3 flex gap-5 text-[11px]"><span className="flex items-center gap-2"><i className="h-2.5 w-2.5 rounded-full bg-[#0f6268]"/>Active members</span><span className="flex items-center gap-2"><i className="h-2.5 w-2.5 rounded-full bg-[#f39a64]"/>Attendance %</span></div></section><section className="repfi-card p-6"><Heading kicker="Revenue split" title="Plan performance"/><div className="mt-4 flex items-center justify-center"><div className="relative h-44 w-44 rounded-full" style={{background:'conic-gradient(#d7f35c 0 52%, #0f6268 52% 83%, #f39a64 83% 100%)'}}><div className="absolute inset-5 grid place-items-center rounded-full bg-[#fbfcfa]"><span className="text-center"><b className="repfi-display block text-2xl">₹8.42L</b><span className="text-[10px] text-[#70808c]">this month</span></span></div></div></div><div className="mt-4 space-y-3 text-xs">{[['Basic','₹2.11L','25%'],['Pro','₹4.78L','57%'],['Elite','₹1.53L','18%']].map(x=><div key={x[0]} className="flex items-center"><span className="flex-1 text-[#70808c]">{x[0]}</span><b>{x[1]}</b><span className="ml-3 w-8 text-right text-[#70808c]">{x[2]}</span></div>)}</div></section></div><div className="mt-8 grid gap-5 lg:grid-cols-2"><section className="repfi-card p-6"><Heading kicker="Coach performance" title="Trainer metrics"/><div className="space-y-3">{trainersData.map(t=><div key={t[0]} className="flex items-center gap-3 rounded-2xl bg-[#f5f7f4] p-3"><span className={`grid h-10 w-10 place-items-center rounded-xl text-xs font-bold ${t[3]}`}>{t[0].split(' ').map(x=>x[0]).join('')}</span><div className="flex-1"><p className="text-sm font-bold">{t[0]}</p><p className="mt-1 text-[11px] text-[#70808c]">{t[1]} sessions delivered</p></div><span className="text-xs font-bold text-[#0f6268]">{t[2]} retention</span></div>)}</div></section><section className="repfi-card p-6"><Heading kicker="Popular programming" title="Workout metrics"/><div className="grid grid-cols-2 gap-3">{[['Push day','628',Dumbbell,'bg-[#d7f35c]'],['Strength 101','492',BarChart3,'bg-[#e1f0ed]'],['HIIT circuit','386',Clock3,'bg-[#fff0e7]'],['Mobility reset','244',Users,'bg-[#eff7c9]']].map(([name,count,I,bg]:any)=><div key={name} className="rounded-2xl bg-[#f5f7f4] p-4"><span className={`grid h-9 w-9 place-items-center rounded-xl ${bg}`}><I size={15}/></span><p className="mt-5 text-sm font-bold">{name}</p><p className="mt-1 text-xs text-[#70808c]"><b className="text-[#20334a]">{count}</b> sessions</p></div>)}</div></section></div></Shell>}
function Router(){return <ErrorBoundary resetKey={useLocation()[0]}><Switch><Route path="/" component={Landing}/><Route path="/dashboard" component={Dashboard}/><Route path="/workouts" component={Workout}/><Route path="/trainers" component={TrainersPage}/><Route path="/progress" component={ProgressPage}/><Route path="/nutrition" component={Nutrition}/><Route path="/ai-coach" component={AICoach}/><Route path="/membership" component={Membership}/><Route path="/admin" component={OwnerDashboard}/><Route path="/admin/members" component={AdminMembers}/><Route path="/admin/analytics" component={Analytics}/><Route component={NotFound}/></Switch></ErrorBoundary>}
function App(){return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><Router/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>}
export default App;